//! 🧪️ The actual paid cursor preserves Unicode, source pointers, bounded copies and every whole release receipt.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
#[test]
fn original_job_source_wire_is_persistent_paid_and_matches_serde_json(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for copy in[1,3,64]{let source:OriginalJobSource=serde_json::from_value(corpus["source"].clone()).unwrap();let oracle=serde_json::to_vec(&source).unwrap();let pointers=(source.kind.as_ptr(),source.input.as_ref().unwrap().as_ptr());let stock=semio_framework_value::RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,semio_framework_job::logical_now_us,1000000,1000000);let input=RetainedTurnInput{operation:71,generation:3,epoch:23,work:crate::OriginalActorTurnWork{clock_binding:caller.original_clock_binding(),absolute_deadline_us:1000000,fuel:caller.fuel_remaining()},grant:caller.remaining_grant()};let mut owner=OriginalJobSourceWireCursor::new(source,input).ok().unwrap();let policy=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..stock};let zero=semio_framework_value::RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(zero,|cx|owner.advance(cx).map_err(Into::into)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for turn in 0..10000{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(policy,|cx|owner.advance(cx).map_err(Into::into)));let ready=result.unwrap();let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.copied_items<=1);assert!(receipt.copied_bytes<=copy);let original=owner.original().unwrap();assert_eq!((original.kind.as_ptr(),original.input.as_ref().unwrap().as_ptr()),pointers);if ready{break}assert!(turn<9999)}assert_eq!(owner.prepared_bytes().unwrap(),oracle);assert_eq!(std::str::from_utf8(owner.prepared_bytes().unwrap()).unwrap(),corpus["expected"].as_str().unwrap());let mut wire=caller.turn(stock,|cx|owner.take_prepared(cx).map_err(Into::into)).unwrap();assert!(owner.retirement_demands(copy).is_err());assert!(caller.turn(stock,|cx|owner.return_wire(&mut wire,cx).map_err(Into::into)).unwrap());assert!(wire.is_none());assert!(owner.retirement_demands(copy).is_err());assert!(caller.turn(stock,|cx|owner.acknowledge_source_closed(cx).map_err(Into::into)).unwrap());owner.begin_close();for turn in 0..1000{if owner.terminal_is_empty(){break}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(policy,|cx|owner.close_step(cx).map_err(Into::into)).unwrap());let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(turn<999)}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(stock);}eprintln!("[DEBUG] Original source wire copy1/3/64,item1 preserves source pointers, exact serde Unicode/escape/binary JSON, zero denial0heap, actual loan/guestACK and every System birth/release receipt");}
